import{_ as n,o as t,c as s,a2 as e}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"AgentPay 与 x402","description":"x402 回答\\"怎么付\\"，AgentPay 回答\\"该不该付\\"：两者的分工、配合方式，以及为什么用了 x402 仍然需要金融控制","frontmatter":{"title":"AgentPay 与 x402","description":"x402 回答\\"怎么付\\"，AgentPay 回答\\"该不该付\\"：两者的分工、配合方式，以及为什么用了 x402 仍然需要金融控制"},"headers":[],"relativePath":"zh/learn/03-infra-map/agentpay-vs-x402.md","filePath":"zh/learn/03-infra-map/agentpay-vs-x402.md","lastUpdated":1792590840000}'),p={name:"zh/learn/03-infra-map/agentpay-vs-x402.md"};function o(l,a,r,i,d,g){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="agentpay-与-x402" tabindex="-1">AgentPay 与 x402 <a class="header-anchor" href="#agentpay-与-x402" aria-label="Permalink to &quot;AgentPay 与 x402&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 尚未经过独立安全审计，请勿用于生产环境的真实资金。</p></div><h2 id="一句话结论" tabindex="-1">一句话结论 <a class="header-anchor" href="#一句话结论" aria-label="Permalink to &quot;一句话结论&quot;">​</a></h2><blockquote><p><strong>x402 回答&quot;怎么付&quot;，AgentPay 回答&quot;该不该付&quot;。</strong></p></blockquote><p>x402 是一个让 HTTP 请求能够携带付款的开放协议。AgentPay 是放在 Agent 与这个协议之间的控制层：协议负责把款付出去，控制层负责决定要不要让它付出去。两者是配合关系，而不是替代关系。</p><h2 id="先简单了解-x402" tabindex="-1">先简单了解 x402 <a class="header-anchor" href="#先简单了解-x402" aria-label="Permalink to &quot;先简单了解 x402&quot;">​</a></h2><p>HTTP 协议里有一个很早就预留、却很少被使用的状态码：<strong>402 Payment Required</strong>。x402 把它真正用了起来，流程大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 买方请求一个资源</span></span>
<span class="line"><span>2. 卖方返回 402，并在响应头里说明：价格、收款地址、币种、网络、有效期</span></span>
<span class="line"><span>3. 买方按要求签署一份付款授权，放进请求头，重新发起请求</span></span>
<span class="line"><span>4. 卖方（或其清算服务）验证授权，返回资源</span></span>
<span class="line"><span>5. 授权随后被提交结算</span></span></code></pre></div><p>这个设计的好处是：付款直接发生在 HTTP 请求里，不需要账号、订阅或预充值，非常适合 Agent 这种&quot;临时需要、按次付费、没有人在旁边&quot;的场景。</p><p>AgentPay 使用的是 <strong>x402 V2</strong>，对应的两个关键请求头是 <code>PAYMENT-REQUIRED</code>（卖方发出的付款要求）和 <code>PAYMENT-SIGNATURE</code>（买方回传的签名授权）。</p><h2 id="一个重要的事实-协议本身不判断该不该付" tabindex="-1">一个重要的事实：协议本身不判断该不该付 <a class="header-anchor" href="#一个重要的事实-协议本身不判断该不该付" aria-label="Permalink to &quot;一个重要的事实：协议本身不判断该不该付&quot;">​</a></h2><p>协议要解决的是<strong>互操作</strong>：让不同的买方和卖方用同一种格式交换&quot;要多少钱&quot;和&quot;这是授权&quot;。它假设客户端自己知道什么时候该付。</p><p>于是一个直接用协议的客户端，行为通常是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收到 402 → 解析要求 → 签名 → 重试</span></span></code></pre></div><p>这条流程里没有&quot;等一下，这笔钱该不该花&quot;这一步。换句话说：</p><ul><li>卖方说要 20 USDC，客户端照签；</li><li>卖方的地址换成了陌生地址，客户端照签；</li><li>循环里每一次重试都收到 402，客户端每次都签。</li></ul><p>协议本身没有错，它只是不负责这件事。<strong>这是分工，而不是缺陷</strong>，但对于一个会自主行动、可能出错的 Agent 来说，这一步必须有人负责。</p><h2 id="它们各管什么" tabindex="-1">它们各管什么 <a class="header-anchor" href="#它们各管什么" aria-label="Permalink to &quot;它们各管什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>x402</th><th>AgentPay</th></tr></thead><tbody><tr><td><strong>回答的问题</strong></td><td>怎么付</td><td>该不该付，失败了怎么办</td></tr><tr><td><strong>所处的层</strong></td><td>支付协议</td><td>金融控制（以及围绕它的网关、账本和审计）</td></tr><tr><td><strong>典型职责</strong></td><td>付款要求的格式、授权签名的格式、验证与结算流程</td><td>单笔上限、滚动预算、白名单、熔断、原子预留、状态恢复、审计</td></tr><tr><td><strong>关注的对象</strong></td><td>一次付款交换</td><td>一个 Agent 在一段时间内的全部支出行为</td></tr><tr><td><strong>是否有状态</strong></td><td>以单次交换为主</td><td>有，需要记住预算、频率和每笔付款的进展</td></tr><tr><td><strong>谁制定</strong></td><td>开放协议社区</td><td>AgentPay 项目</td></tr></tbody></table><h2 id="它们怎么配合" tabindex="-1">它们怎么配合 <a class="header-anchor" href="#它们怎么配合" aria-label="Permalink to &quot;它们怎么配合&quot;">​</a></h2><p>下面是买方通过 x402 链上支付时，两者在同一条请求里的位置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 请求资源</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>卖方返回 402 + 付款要求                     ← x402：付款要求的格式</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│ AgentPay 金融防火墙           │            ← AgentPay：该不该付？</span></span>
<span class="line"><span>│ 单笔上限 · 预算 · 白名单 · 熔断 │</span></span>
<span class="line"><span>└──────┬──────────────┬───────┘</span></span>
<span class="line"><span>     放行            拒绝</span></span>
<span class="line"><span>       │              │</span></span>
<span class="line"><span>       ▼              └─▶ 不签名，原因反馈给 Agent</span></span>
<span class="line"><span>预留额度 → 签名授权                          ← x402：授权的格式</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>带着 PAYMENT-SIGNATURE 重试                  ← x402</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>卖方验证 → 返回资源 → 异步结算</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>AgentPay：提交或释放预留，记录审计            ← AgentPay：收尾与追溯</span></span></code></pre></div><p>可以看到，AgentPay 在 x402 流程的<strong>前后各插入了一段</strong>：签名之前判断，结算之后收尾。x402 的格式和流程本身没有被改变，所以对卖方来说，它看到的仍然是一份标准的付款授权。</p><h2 id="agentpay-比-x402-多出来的部分" tabindex="-1">AgentPay 比 x402 多出来的部分 <a class="header-anchor" href="#agentpay-比-x402-多出来的部分" aria-label="Permalink to &quot;AgentPay 比 x402 多出来的部分&quot;">​</a></h2><p><strong>1. 付款之前的规则判断。</strong> 这是最核心的一点，见 <a href="./../04-agentpay-concepts/financial-firewall">为什么需要金融防火墙</a>。</p><p><strong>2. 并发下的预算保护。</strong> 协议不记录你花了多少，更不会在并发请求之间协调预算，见 <a href="./../04-agentpay-concepts/budget-reservation">预算预留</a>。</p><p><strong>3. 出问题之后的处理。</strong> 付款成功但响应超时怎么办？结算结果未知怎么办？这些超出了协议的范围，见 <a href="./../04-agentpay-concepts/timeout-is-not-failure">超时不等于失败</a>。</p><p><strong>4. 第二条支付路径。</strong> x402 面向链上支付。AgentPay 还提供平台虚拟钱包：携带 API Key 的请求直接从租户钱包扣费，不需要每笔都上链，延迟更低。两条路径由凭证决定走哪一条，<strong>余额不足时不会静默切换到链上</strong>，避免产生非预期的链上支出。</p><p><strong>5. 卖方的收费网关与管理能力。</strong> 把已有 API 变成收费接口、配置价格与策略、发布与回滚、查看消费与审计，这些是围绕协议的上层产品能力。</p><h2 id="用-agentpay-会不会-被绑定" tabindex="-1">用 AgentPay 会不会&quot;被绑定&quot;？ <a class="header-anchor" href="#用-agentpay-会不会-被绑定" aria-label="Permalink to &quot;用 AgentPay 会不会&quot;被绑定&quot;？&quot;">​</a></h2><p>AgentPay 在链上路径上遵循 x402 V2 的格式，并且在项目内部以测试向量验证编码与签名的一致性。同时，AgentPay 的核心库没有强依赖第三方的 x402 软件包，而是按规范自行实现编解码；如果你同时使用官方库，可以通过可选的互通工具在两边的对象之间转换。</p><p>需要说明的是，平台虚拟钱包这条路径不使用 x402 的付款头，而是使用 API Key。因此&quot;AgentPay&quot;并不等同于&quot;x402 的某个实现&quot;，x402 只是它支持的支付方式之一。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：我已经在用 x402 了，为什么还要 AgentPay？</strong> 如果你的 Agent 只在受控环境里、预算很小、你自己盯着，x402 可能就够了。当 Agent 自主运行、有多个并发、花的是真钱，或者有多个 Agent 共用预算，就需要在协议之上加一层控制。</p><p><strong>Q：我可以自己在 x402 客户端外面写一层检查吗？</strong> 可以，简单的单笔上限很容易写。但要做对并发预算、签名后超时的处理、熔断和审计，需要处理的细节很多，这些正是 AgentPay 想一次做好的部分。</p><p><strong>Q：AgentPay 会替代 x402 吗？</strong> 不会。链上支付路径依赖 x402，AgentPay 的价值在协议之上，而不是替代协议。</p><p><strong>Q：AgentPay 能和任意 x402 卖方互通吗？</strong> AgentPay 按 x402 V2 规范实现，并有协议测试向量验证。与第三方实现的互通性仍需要以实际测试为准，项目目前处于实验阶段。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想知道 AgentPay 在整个体系中的完整位置：<a href="./where-agentpay-fits">AgentPay 的位置</a></li><li>想理解 402 与 x402 的原理：<a href="./../02-agent-payments/http-402-and-x402">HTTP 402 与 x402</a></li><li>想看到两者配合的效果：<a href="./../05-hands-on/ten-minute-demo">10 分钟 Demo</a></li></ul><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="/docs/specs/protocol-consistency">协议一致性契约</a>：付款头、双轨支付裁定与错误码</li><li><a href="/docs/specs/adr-001">ADR-001：x402 的复用与自研决策</a>：为什么核心库自行实现协议编解码</li></ul>`,41)])])}const u=n(p,[["render",o]]);export{h as __pageData,u as default};
